CREATE TABLE livestock_listings(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`livestock_id` bigint  NOT NULL,`farmer_id` bigint  NOT NULL,`title` varchar(255)  NOT NULL,`description` text  NULL,`species` varchar(100)  NOT NULL COMMENT 'cattle, goat, sheep, poultry, buffalo',`breed` varchar(255)  NOT NULL,`age_years` INT  NULL COMMENT 'Age in years',`age_months` INT  NULL COMMENT 'Additional months beyond years',`gender` varchar(50)  NOT NULL COMMENT 'male, female, mixed',`quantity` INT  NOT NULL DEFAULT 1,`purpose` varchar(100)  NOT NULL COMMENT 'dairy, meat, breeding, draft, eggs',`price` DECIMAL(12,2)  NOT NULL COMMENT 'Price in INR',`price_negotiable` TINYINT(1)  DEFAULT 1,`weight_kg` DECIMAL(10,2)  NULL COMMENT 'Weight in kilograms',`health_status` varchar(100)  DEFAULT 'healthy' COMMENT 'healthy, recovering, pregnant, lactating',`vaccination_status` varchar(100)  NULL COMMENT 'up_to_date, partial, none',`last_vaccination_date` date  NULL,`milk_production_liters` DECIMAL(10,2)  NULL COMMENT 'Daily milk production for dairy animals',`breeding_certified` TINYINT(1)  DEFAULT 0,`breeding_certification_number` varchar(255)  NULL,`genetic_lineage` text  NULL COMMENT 'Parent breed information and lineage',`photos` text  NULL COMMENT 'JSON array of S3 photo URLs',`videos` text  NULL COMMENT 'JSON array of S3 video URLs',`location_state` varchar(100)  NOT NULL,`location_district` varchar(100)  NOT NULL,`location_village` varchar(100)  NULL,`latitude` DECIMAL(10,8)  NULL COMMENT 'GPS latitude (optional)',`longitude` DECIMAL(11,8)  NULL COMMENT 'GPS longitude (optional)',`pincode` varchar(10)  NULL,`address_line` varchar(255)  NULL COMMENT 'Full livestock listing address',`farmer_contact_phone` varchar(20)  NULL,`farmer_contact_email` varchar(255)  NULL,`status` varchar(50)  DEFAULT 'active' COMMENT 'active, sold, reserved, inactive',`views_count` INT  DEFAULT 0,`interest_count` INT  DEFAULT 0,`inquiry_count` INT  DEFAULT 0,`featured` TINYINT(1)  DEFAULT 0,`featured_until` timestamp  NULL)ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;